def _q(name):
    return '"' + name.replace('"', '""') + '"'


def _json(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(',', ':'), allow_nan=False)


_PAGED_PARENT_METER_V2=ContextVar('c09_authority_paged_parent_meter_v2',default=None)


class C09AuthorityRowMeterV2:
    """A local report view over the caller's one actual reserved SQL meter."""
    __slots__ = ('limit','parent','_read_start','_write_start','_encode_start')

    def __init__(self, limit):
        from ..runtime.c09_paged_sql_v2 import current_c09_sql_meter_v2
        self.limit = limit
        self.parent = current_c09_sql_meter_v2()
        self._read_start = self.parent.read_bytes
        self._write_start = self.parent.written_bytes
        self._encode_start = self.parent.encoded_bytes

    @property
    def related_read_bytes(self):
        return (self.parent.read_bytes-self._read_start
                + self.parent.encoded_bytes-self._encode_start)

    @property
    def target_write_bytes(self):
        return self.parent.written_bytes-self._write_start

    @property
    def remaining_bytes(self):
        return min(self.limit-self.related_read_bytes-self.target_write_bytes,
                   self.parent.remaining_bytes)

    def charge_read(self, count):
        if type(count) is not int or count < 0 or count > self.remaining_bytes:
            raise C09PagedCaptureHold('related read exceeds this C09 quantum')
        self.parent.charge_read(count)

    def charge_write(self, count):
        if type(count) is not int or count < 0 or count > self.remaining_bytes:
            raise C09PagedCaptureHold('target write exceeds this C09 quantum')
        self.parent.charge_write(count)

    def charge_encode(self, count):
        if type(count) is not int or count < 0 or count > self.remaining_bytes:
            raise C09PagedCaptureHold('encoded output exceeds this C09 quantum')
        self.parent.charge_encode(count)

    def encode(self, value):
        encoded = canonical_serialize(value).encode('utf-8')
        # canonical_serialize charged the string; this is the real bytes copy.
        self.charge_encode(len(encoded))
        return encoded

    def read_one(self, db, table, columns, where, args=()):
        from ..runtime.c09_paged_sql_v2 import _sql_scalar_size_v2
        sizes = ','.join('length(CAST('+_q(col)+' AS BLOB))' for col in columns)
        query = ' FROM '+_q(table)+' WHERE '+where+' LIMIT 1'
        self.parent.require_available(len(columns)*8)
        metadata = db.execute('SELECT '+sizes+query, args).fetchone()
        self.charge_read(0 if metadata is None else sum(map(_sql_scalar_size_v2,metadata)))
        if metadata is None:
            return None
        amount = sum(size or 0 for size in metadata)
        if amount * 6 + len(columns)*32 > self.remaining_bytes:
            raise C09PagedCaptureHold('related original needs its bounded cell codec')
        row = db.execute('SELECT '+','.join(map(_q,columns))+query,args).fetchone()
        if row is None:
            raise C09PagedCaptureHold('frozen related original disappeared')
        self.charge_read(amount)
        return row

    def write(self, db, sql, args=()):
        from ..runtime.c09_paged_sql_v2 import _sql_scalar_size_v2
        amount=len(sql.encode('utf-8'))+sum(map(_sql_scalar_size_v2,args))
        self.charge_write(amount)
        self.parent.count_mutation()
        return db.execute(sql,args)


def _same_insert(db, table, columns, row, key_columns, meter):
    key = tuple(row[columns.index(name)] for name in key_columns)
    where = ' AND '.join(_q(name)+'=?' for name in key_columns)
    prior = meter.read_one(db,table,columns,where,key)
    if prior is not None:
        if prior != row:
            raise C09PagedCaptureHold('candidate identity conflicts: '+table)
        return False
    meter.write(db,'INSERT INTO '+_q(table)+'('+','.join(map(_q,columns))+') VALUES('+
                ','.join('?' for _ in row)+')',row)
    return True


def _shape_key(shape,row):
    return tuple(row[shape.columns.index(name)] for name in shape.primary_key_columns)


def _generated(pair, scope, table, columns, row, producer, original_digest, meter):
    shape = read_c09_table_shape_v2(pair.candidate,table)
    key = _shape_key(shape,row)
    commitment = legacy._row_commitment(table,columns,row)
    meter.charge_encode(len(legacy._canonical((table,columns,tuple(legacy._cell(v) for v in row)))))
    values = (scope.scope_digest,scope_role(pair),table,canonical_digest(key),_json(key),
              producer,original_digest,commitment)
    _same_insert(pair.candidate,'authority_c09_role_generated_v2',
        ('scope_digest','role','table_name','key_digest','key_json','producer',
         'original_digest','new_commitment'),values,
        ('scope_digest','role','table_name','key_digest'),meter)


def scope_role(pair):
    return pair.source_original.role


class _AuthorityRowTransformV2:
    """One actual source row; all cross-row state remains indexed on disk."""
    __slots__ = ('pair','scope','basis','facts','completion','role','origin','probe','probe_seen','source_physical_census_v3','habit_current_v1')

    def __init__(self,pair,scope,basis):
        self.pair,self.scope,self.basis = pair,scope,basis
        from .c09_paged_recovery_facts_v2 import C09PagedRecoveryFactsResolverV2
        if type(basis.facts) is not C09PagedRecoveryFactsResolverV2:
            raise AuthorityUnavailable('actual installed recovery resolver required')
        self.facts = basis.facts
        self.completion = self.facts.require_complete(
            scope_digest=scope.scope_digest,facts_pin_digest=basis.pin_digest,
            graph_issue_digest=basis.graph_issue_digest)
        self.role = scope_role(pair)
        self.origin=None;self.probe=None;self.probe_seen=False;self.source_physical_census_v3=None;self.habit_current_v1=None

    def _consume(self,kind,item,operation,commitment,meter):
        if self.probe==(kind,item,operation,commitment): self.probe_seen=True
        identifier(item,'consumed item_id'); identifier(operation,'consumed operation_id')
        columns=('namespace','kind','item_id','operation_id','original_commitment','facts_pin_digest')
        key=(self.scope.authority_namespace,kind,item)
        prior=None
        if self.pair.source.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='authority_c09_consumed_execution_v1'").fetchone():
            prior=meter.read_one(self.pair.source,'authority_c09_consumed_execution_v1',
                columns,'namespace=? AND kind=? AND item_id=?',key)
        if prior is not None and prior[3:5] != (operation,commitment):
            raise C09PagedCaptureHold('current suffix reused consumed identity')
        row=prior or (*key,operation,commitment,self.completion.pin_digest)
        inserted=_same_insert(self.pair.candidate,'authority_c09_consumed_execution_v1',
                             columns,row,columns[:3],meter)
        if inserted and prior is None:
            if self.origin is None: raise C09PagedCaptureHold('consumed identity has no actual producer origin')
            origin=(self.scope.scope_digest,kind,item,*self.origin)
            _same_insert(self.pair.candidate,'authority_c09_consumed_origins_v2',
                ('scope_digest','kind','item_id','origin_kind','origin_table','origin_key_json'),
                origin,('scope_digest','kind','item_id'),meter)
            _generated(self.pair,self.scope,'authority_c09_consumed_execution_v1',
                       columns,row,'verified_recovery_identity_v2',self.completion.pin_digest,meter)

    def __call__(self,db,shape,key,old,remaining):
        from ..runtime.c09_paged_capture_contract_v2 import meter_c09_commitments_v2
        meter=C09AuthorityRowMeterV2(remaining)
        with meter_c09_commitments_v2(meter):
            return self._apply_row(db,shape,key,old,meter)

    def _apply_row(self,db,shape,key,old,meter):
        if db is not self.pair.candidate:
            raise C09PagedCaptureHold('row write is outside its registered role pair')
        self.origin=('source_row',shape.table,_json(key))
        self.basis.require_current()
        if self.role=='core':
            new,kind=self._core(shape,old,meter)
        elif self.role=='execution':
            new,kind=self._execution(shape,old,meter)
        elif self.role=='deletion':
            new,kind=old,'preserved_exact'
        else:
            raise C09PagedCaptureHold('authority builder cannot transform Graph')
        old_digest=legacy._row_commitment(shape.table,shape.columns,old)
        new_digest=None if new is None else legacy._row_commitment(shape.table,shape.columns,new)
        meter.charge_encode(len(legacy._canonical((shape.table,shape.columns,tuple(legacy._cell(v) for v in old)))))
        if new is not None:
            meter.charge_encode(len(legacy._canonical((shape.table,shape.columns,tuple(legacy._cell(v) for v in new)))))
            if shape.table=='sqlite_sequence':
                found=meter.read_one(db,shape.table,shape.columns,'name=?',(new[0],))
                if found is None: meter.write(db,'INSERT INTO sqlite_sequence(name,seq) VALUES(?,?)',new)
                else: meter.write(db,'UPDATE sqlite_sequence SET seq=? WHERE name=?',(new[1],new[0]))
            else:
                _same_insert(db,shape.table,shape.columns,new,shape.primary_key_columns,meter)
        values=(self.scope.scope_digest,self.role,shape.table,canonical_digest(key),
                _json(key),old_digest,kind,new_digest)
        _same_insert(db,'authority_c09_role_rows_v2',
            ('scope_digest','role','table_name','key_digest','key_json',
             'old_commitment','disposition','new_commitment'),values,
            ('scope_digest','role','table_name','key_digest'),meter)
        digest=canonical_digest(('sylanne3.c09.authority-row-disposition.v2',values))
        meter.charge_encode(len(canonical_serialize(('sylanne3.c09.authority-row-disposition.v2',values)).encode('utf-8')))
        return C09RowTransformResultV2(digest,meter.related_read_bytes,meter.target_write_bytes)

    def _core(self,shape,old,meter):
        table,columns=shape.table,shape.columns
        if table in legacy._HABIT_CORE_TABLES:
            from .c09_habit_policy_rows_v1 import transform_habit_core_row_v1
            return transform_habit_core_row_v1(self,shape,old,meter)
        namespace=self.scope.authority_namespace
        from ..segmented_sql_cell_v1 import DDLS as PHYSICAL_CONTAINER_DDLS
        if table in PHYSICAL_CONTAINER_DDLS:
            from .c09_source_physical_read_v3 import VerifiedSourcePhysicalContainerCensusV3
            proof=self.source_physical_census_v3
            if (type(proof) is not VerifiedSourcePhysicalContainerCensusV3 or proof.scope.pair is not self.pair
                    or proof.scope.session is not self.basis.session):
                raise C09PagedCaptureHold('physical Source retirement requires actual complete same-role container census')
            proof.require_current(meter=meter.parent)
            expected=meter.read_one(self.pair.source,'sqlite_master',('sql',),'type=? AND name=?',('table',table))
            if expected!=(PHYSICAL_CONTAINER_DDLS[table],):raise C09PagedCaptureHold('actual physical Source retirement schema differs')
            return None,'retired_physical_container_v3'
        if table=='authority_owner_goal_cancellations_v1':
            from .owner_goal_cancellation_contract_v1 import (
                GOAL_CANCEL_DDL_V1,validate_goal_cancellation_core_row_v1)
            actual=meter.read_one(self.pair.source,'sqlite_master',('sql',),
                'type=? AND name=?',('table',table))
            if actual!=(GOAL_CANCEL_DDL_V1,):
                raise C09PagedCaptureHold('actual Goal cancellation schema differs')
            value=validate_goal_cancellation_core_row_v1(columns,old)
            if value.request.authority_namespace==namespace:
                value.require_signature_v1(self.facts.original_port.budget_job_issuer)
            return old,'preserved_exact'
        if table=='sqlite_sequence': return old,'preserved_exact'
        ns = old[columns.index('namespace')] if 'namespace' in columns else None
        commitment=lambda: legacy._row_commitment(table,columns,old)
        if table=='authority_natural_disposition_originals_v1':
            from .natural_disposition_maintenance_v1 import ORIGINAL_COLUMNS,core_original_from_wire_v1
            if columns!=ORIGINAL_COLUMNS: raise C09PagedCaptureHold('natural disposition columns differ')
            value=core_original_from_wire_v1(json.loads(old[5]))
            if value.authority_namespace==namespace:
                self._consume('natural_disposition_original_v1',value.original_ref,value.operation_id,value.digest,meter)
                return None,'derived_removed'
        elif table=='authority_worker_result_read_attempts_v1':
            from .v2_worker_model_result_attempts import validate_worker_result_read_attempt_row_v1
            attempt=validate_worker_result_read_attempt_row_v1(columns,old)
            self.facts.worker_attempt_fence(attempt,meter=meter)
            self.facts.c4proof(attempt,meter=meter)
            request=attempt.request
            if request.authority_namespace==namespace:
                self._consume('worker_result_read_attempt',request.read_attempt_id,
                              request.consumer_operation_id,commitment(),meter)
                return None,'payload_erased_retained_facts'
        elif table in legacy.MODEL_TABLES:
            from .c09_model_budget_original_v1 import validate_model_core_row_v1
            call=validate_model_core_row_v1(table,columns,old)
            original=self.facts.lookup_model_original(call,meter=meter)
            if original is None:
                prior=meter.read_one(self.pair.source,'authority_c09_consumed_execution_v1',
                    ('item_id',),'namespace=? AND kind=? AND item_id=?',(namespace,'model_call',call)) if _has_table(self.pair.source,'authority_c09_consumed_execution_v1',meter) else None
                if prior is not None and table=='authority_model_egress_observations_v1':
                    raise C09PagedCaptureHold('historical retired model body survived')
            else:
                self._verify_model(original,meter)
                for kind,item in (('model_call',call),('model_operation',original.model_operation_id),
                    ('model_job',original.job_id),('model_acquire',original.acquire_operation_id),
                    ('model_admission',original.admission_id_or_none)):
                    if item is not None: self._consume(kind,item,original.model_operation_id,original.original_digest,meter)
                if table=='authority_model_egress_observations_v1': return None,'payload_erased_retained_facts'
                if table=='authority_model_egress_observation_status_v1':
                    new=(*old[:-1],1)
                    return new,'preserved_exact' if new==old else 'payload_erased_retained_facts'
        elif table in _D12_TABLES:
            from .d12_c09_core_rows_v1 import validate_d12_core_row_v1
            actual_ns,kind,item,operation=validate_d12_core_row_v1(table,columns,old)
            if actual_ns!=namespace: return old,'preserved_exact'
            if table=='authority_d12_operation_originals_v1':
                from .owner_stop_reply_v1 import PLAN_SCHEMA
                if json.loads(old[7]).get('schema')==PLAN_SCHEMA:
                    proof=self.facts.owner_reply_stop(old[:3],old,meter=meter)
                    if proof is None or proof[0]!=old: raise C09PagedCaptureHold('actual StopReply closure unavailable')
                    if proof[1]=='preserved_exact': return old,'preserved_exact'
                    if proof[1]!='derived_removed': raise C09PagedCaptureHold('unknown StopReply disposition')
                    self._consume('owner_reply_cycle_stop_v1',proof[2],old[1],proof[3],meter)
            self._consume(kind,item,operation or self.scope.operation_id,commitment(),meter)
            if table=='authority_d12_operation_originals_v1':
                self._consume('d12_source_original',old[8],old[1],legacy._digest((old[0],old[1],old[8])),meter)
            if table=='authority_d12_lifecycle_heads_v1':
                if old[2]!='active': raise C09PagedCaptureHold('unfinished installation lifecycle')
                from ..runtime.lifecycle_operations_v1 import digest
                new=(old[0],old[1],'active',old[3]+1,None,
                    digest((old[0],old[1],'active',old[3]+1,'c09_rebase',self.scope.operation_id,self.completion.pin_digest)),None)
                return new,'rebuilt_from_surviving_sources'
            return None,'payload_erased_retained_facts'
        elif table=='authority_namespaces' and ns==namespace:
            get=lambda name: old[columns.index(name)]
            if (get('execution_journal_id'),get('execution_seq'),get('execution_digest')) != (
                    self.completion.old_journal_id,self.completion.old_seq,self.completion.old_digest):
                raise C09PagedCaptureHold('Core execution head differs from verified facts pin')
            new=list(old)
            for name,value in (('execution_journal_id',self.pair.build_plan['new_execution_journal_id']),
                ('execution_seq',0),('execution_digest','genesis'),
                ('revocation_epoch',get('revocation_epoch')+1),('anchor_nonce',self.pair.build_plan['new_anchor_nonce'])):
                new[columns.index(name)]=value
            return tuple(new),'rebuilt_from_surviving_sources'
        elif table in ('authority_v2_fences','authority_v2_mutations') and ns==namespace:
            operation=old[columns.index('operation_id')]
            if table=='authority_v2_fences':
                retained=self.basis.require_source_qualified_natural_final_core_row_v4(
                    table,columns,old,meter=meter)
                if retained is not None:
                    return old,'preserved_exact'
            if table=='authority_v2_fences' and operation.startswith('foreground-domain-'):
                verified=self.facts.foreground_fence(operation,old,meter=meter)
                if verified is None or verified[0]!=old: raise C09PagedCaptureHold('foreground fence closure unavailable')
                if verified[1]=='preserved_exact': return old,'preserved_exact'
                if verified[1]!='derived_removed': raise C09PagedCaptureHold('foreground disposition unknown')
            if table=='authority_v2_mutations' and old[columns.index('mutation_kind')]=='deletion':
                return old,'preserved_exact'
            if table=='authority_v2_fences':
                from .v2_contract import decode_bytes
                permit=decode_bytes(old[columns.index('permit')])
                if permit.operation=='delete':
                    if old[columns.index('state')]=='active':
                        accepted=self.basis.accepted_receipt
                        if permit.operation_id!=accepted.pending.permit.operation_id:
                            raise C09PagedCaptureHold('unrelated active deletion fence')
                    if old[columns.index('state')]=='active':
                        continuation=self._continuation(permit,meter)
                        values=list(old)
                        from .v2_contract import canonical_bytes
                        for field,value in (('token',continuation.token),('fence_epoch',continuation.fence_epoch),
                            ('revision',continuation.revision),('permit',canonical_bytes(continuation))):
                            values[columns.index(field)]=value
                        return tuple(values),'rebuilt_from_surviving_sources'
                    return old,'preserved_exact'
            state=old[columns.index('state')]
            if state=='pending': raise C09PagedCaptureHold('unappended execution obligation')
            if table=='authority_v2_fences' and state=='active' and old[columns.index('pending')] is not None:
                raise C09PagedCaptureHold('live dispatch must drain')
            kind='mutation' if table=='authority_v2_mutations' else 'fence'
            item=old[columns.index('mutation_id')] if kind=='mutation' else operation
            self._consume(kind,item,operation,commitment(),meter)
            return None,'payload_erased_retained_facts'
        elif table=='authority_v2_epochs' and ns==namespace:
            active=self._active_deletion_permit(meter)
            if active is not None:
                values=list(old);values[columns.index('last_epoch')]=active.fence_epoch+1
                return tuple(values),'preserved_exact' if tuple(values)==old else 'rebuilt_from_surviving_sources'
        elif table=='authority_c09_consumed_execution_v1' and ns==namespace:
            self._consume(old[1],old[2],old[3],old[4],meter)
        elif table in SINGLETONS and ns==namespace:
            kind,json_column,digest_column=SINGLETONS[table]
            raw=old[columns.index(json_column)]
            original=json.loads(raw)
            operation=old[columns.index('operation_id')]
            archive=(namespace,operation,kind,original[digest_column],raw,
                     self.scope.maintenance_generation if operation==self.scope.operation_id else self.scope.maintenance_generation-1)
            archive_columns=('namespace','operation_id','original_kind','original_digest','original_json','maintenance_generation')
            # Prior immutable archive generation wins; old bytes/digest must match.
            prior=meter.read_one(self.pair.source,'authority_c09_originals_archive_v1',
                archive_columns,'namespace=? AND operation_id=? AND original_kind=?',archive[:3]) if _has_table(self.pair.source,'authority_c09_originals_archive_v1',meter) else None
            if prior is not None and prior[3:5]!=archive[3:5]: raise C09PagedCaptureHold('immutable archive original conflicts')
            value=prior or archive
            if _same_insert(self.pair.candidate,'authority_c09_originals_archive_v1',archive_columns,value,archive_columns[:3],meter) and prior is None:
                _generated(self.pair,self.scope,'authority_c09_originals_archive_v1',archive_columns,value,
                           'archive_exact_original_v2',original[digest_column],meter)
            replacement=self.facts.current_singleton(table,meter=meter)
            if table=='authority_execution_redaction_seals_v3':
                self.basis.require_retired_source_seal(old,meter=meter)
                return None,'payload_erased_retained_facts'
            if replacement is not None:
                return replacement,'payload_erased_retained_facts'
            if table in {'authority_execution_redaction_sidecar_pins_v3','authority_execution_redaction_switches_v3'}:
                return None,'payload_erased_retained_facts'
        elif table=='authority_v2_never_begun':
            from .v2_contract import FenceNeverBegunReceiptV2,canonical_bytes,decode_bytes
            receipt=decode_bytes(old[columns.index('receipt')])
            if type(receipt) is not FenceNeverBegunReceiptV2 or canonical_bytes(receipt)!=old[columns.index('receipt')] or (
                receipt.operation_id,receipt.request_id)!=(old[columns.index('operation_id')],old[columns.index('request_id')]):
                raise C09PagedCaptureHold('never-begun original identity differs')
            if receipt.namespace==namespace:
                self._consume('never_begun_operation',receipt.operation_id,receipt.operation_id,commitment(),meter)
                self._consume('never_begun_request',receipt.request_id,receipt.operation_id,commitment(),meter)
                return None,'payload_erased_retained_facts'
        elif table=='authority_execution_handoff_starts_v1' and ns==namespace:
            raise C09PagedCaptureHold('handoff source lacks registered v2 recovery proof')
        _validate_preserved_core_row(self,table,columns,old,meter,shape=shape)
        return old,'preserved_exact'

    def _verify_model(self,original,meter):
        from .c09_model_budget_original_v1 import model_unit_fact_v4
        fact=self.facts.lookup_execution(original.call_id,meter=meter)
        binding=self.facts.lookup_execution_binding(original.call_id,meter=meter)
        settlements=tuple(sorted(model_unit_fact_v4(original,u).settlement_id for u in original.units if u.actual_or_none is not None))
        if fact is None or binding is None or binding.execution_kind!='model' or (
            fact.signature_commitment,fact.input_commitment,binding.originating_journal_id)!=(
            original.original_digest,original.request_digest,original.originating_journal_id) or (
            original.original_digest not in binding.source_row_commitments or binding.d11_settlement_ids!=settlements):
            raise C09PagedCaptureHold('model actual cost is not bound to recovery facts')
        for settlement in settlements:
            if self.facts.lookup_d11(settlement,meter=meter) is None:
                raise C09PagedCaptureHold('model settlement original absent')

    def _execution(self,shape,old,meter):
        if shape.table in {'authority_v2_execution_entries','authority_v2_execution_redacted_prefix_v4'}:
            return None,'payload_erased_retained_facts'
        if shape.table!='authority_v2_execution_meta' or shape.columns!=('key','value'):
            raise C09PagedCaptureHold('unclassified execution table/columns')
        key,value=old
        expected={'namespace':self.scope.authority_namespace,
                  'journal_id':self.completion.old_journal_id}
        if key in expected and value!=expected[key]:
            raise C09PagedCaptureHold('source execution metadata differs from facts pin')
        if key=='schema_version':
            if value not in {'1','2','4'}: raise C09PagedCaptureHold('unknown execution schema')
            updated='4'
        elif key=='journal_id': updated=self.pair.build_plan['new_execution_journal_id']
        elif key=='core_redaction_source': updated=self._execution_core_source()
        else: updated=value
        return (key,updated),'preserved_exact' if updated==value else 'rebuilt_from_surviving_sources'

    def _execution_core_source(self):
        from .v2_execution_journal import _CORE_SEAL_SOURCE_SCHEMA
        return json.dumps(dict(schema=_CORE_SEAL_SOURCE_SCHEMA,core_path=self.basis.new_core_path,
            authority_id=self.scope.authority_id,namespace=self.scope.authority_namespace,
            journal_id=self.pair.build_plan['new_execution_journal_id']),sort_keys=True,separators=(',',':'))


    def _active_deletion_permit(self,meter):
        from .v2_contract import decode_bytes
        shape=read_c09_table_shape_v2(self.pair.source,'authority_v2_fences')
        operation=self.basis.accepted_receipt.pending.permit.operation_id
        row=meter.read_one(self.pair.source,shape.table,shape.columns,'namespace=? AND operation_id=?',
            (self.scope.authority_namespace,operation))
        if row is None or row[shape.columns.index('state')]!='active': return None
        permit=decode_bytes(row[shape.columns.index('permit')])
        if permit.operation!='delete' or permit.operation_id!=operation:
            raise C09PagedCaptureHold('accepted active deletion original differs')
        return permit


    def _current_anchor(self,meter):
        from ..runtime.restore_anchor import RestoreAnchor
        shape=read_c09_table_shape_v2(self.pair.source,'authority_namespaces')
        old=meter.read_one(self.pair.source,shape.table,shape.columns,'namespace=?',(self.scope.authority_namespace,))
        if old is None: raise C09PagedCaptureHold('source namespace anchor absent')
        get=lambda name: old[shape.columns.index(name)]
        if (get('execution_journal_id'),get('execution_seq'),get('execution_digest'))!=(
            self.completion.old_journal_id,self.completion.old_seq,self.completion.old_digest):
            raise C09PagedCaptureHold('source anchor differs from complete facts pin')
        return RestoreAnchor(self.scope.authority_id,self.scope.authority_namespace,
            get('generation'),get('deletion_journal_id'),get('deletion_seq'),get('deletion_digest'),
            self.pair.build_plan['new_execution_journal_id'],0,'genesis',get('revocation_epoch')+1,
            self.pair.build_plan['new_anchor_nonce'])


    def _continuation(self,permit,meter):
        if self.basis.accepted_receipt.after_anchor.execution_journal_id!=self.completion.old_journal_id:
            raise C09PagedCaptureHold('accepted anchor cannot transfer to new journal')
        return replace(permit,token=self.pair.build_plan['continuation_permit_token'],
            fence_epoch=permit.fence_epoch+1,revision=permit.revision+1,pinned_anchor=self._current_anchor(meter))


def _has_table(db,name,meter):
    return meter.read_one(db,'sqlite_master',('name',),"type='table' AND name=?",(name,)) is not None


def _validate_preserved_core_row(transform,table,columns,row,meter,*,shape):
    if table=='authority_migration_snapshot_certificate_members_v1':
        from .migration_snapshot_certificate_members_v1 import validate_snapshot_certificate_member_row_v1
        if shape.primary_key_columns!=('namespace','transfer_id','member_key') or shape.primary_key_types!=('text','text','text'):
            raise C09PagedCaptureHold('actual migration certificate member exact PK differs')
        return validate_snapshot_certificate_member_row_v1(transform.basis.session._control.maintenance.core,columns,row)
    elif table==D13_RETIREMENT_TABLE:
        from .c09_d13_source_retirement_v3 import COLUMNS,validate_retirement_original_v3
        if columns!=COLUMNS:raise C09PagedCaptureHold('actual bodyless D13 retirement row columns differ')
        original=validate_retirement_original_v3(transform.basis.session._control.maintenance.control,json.loads(row[7]))
        if (row[:7]!=(original['namespace'],original['kind'],original['item_id'],original['phase'],original['counter_operation_id'],
                original['generation_call_id'],original['retirement_digest']) or row[8:]!=(original['key_id'],original['signature'])
                or canonical_serialize(original)!=row[7]):
            raise C09PagedCaptureHold('actual D13 retirement row and immutable signed original differ')
        return original
    elif table=='authority_natural_final_observations_v4':
        from .v2_contract import (decode_bytes,canonical_bytes,AuthorityNaturalFinalEffectObservationV4)
        expected_columns=('authority_namespace','operation_id','observation_kind','permit_digest','original_bytes','original_digest')
        if (tuple(columns)!=expected_columns or len(row)!=len(expected_columns) or shape.columns!=expected_columns
                or shape.primary_key_columns!=expected_columns[:3] or shape.primary_key_types!=('text','text','text')
                or type(row[4]) is not bytes or not row[4]):
            raise C09PagedCaptureHold('natural final Core observation exact row/columns/PK/BLOB differs')
        # The ordinary row engine already reserved the full SQL row before loading it.
        # A cell outside that existing bounded path must use the formal fragment reader.
        if len(row[4])*8>meter.remaining_bytes:
            raise C09PagedCaptureHold('natural final Core observation requires its formal body fragment codec')
        meter.charge_encode(len(row[4]))
        try:value=decode_bytes(row[4])
        except (ValueError,TypeError,UnicodeError) as exc:
            raise C09PagedCaptureHold('natural final Core observation closed original codec differs') from exc
        if type(value) is not AuthorityNaturalFinalEffectObservationV4:
            raise C09PagedCaptureHold('unknown natural final Core observation original kind')
        encoded=canonical_bytes(value);meter.charge_encode(len(encoded))
        permit_bytes=canonical_bytes(value.permit);meter.charge_encode(len(permit_bytes)*2)
        key=(value.authority_namespace,value.operation_id,value.observation_kind)
        ref_bytes=json.dumps(key,separators=(',',':'),ensure_ascii=False).encode('utf-8');meter.charge_encode(len(ref_bytes)*2)
        if (key!=tuple(row[:3]) or row[2]!='effect_inventory' or encoded!=row[4]
                or row[3]!='sha256:'+sha256(permit_bytes).hexdigest()
                or row[5]!='sha256:'+sha256(encoded).hexdigest()
                or value.original_ref!='authority-natural-final-observation:'+sha256(ref_bytes).hexdigest()):
            raise C09PagedCaptureHold('natural final Core observation original bytes/digest/permit/ref association differs')
        if value.authority_namespace==transform.scope.authority_namespace and (
                value.installation_id!=transform.scope.installation_id or value.authority_id!=transform.scope.authority_id):
            raise C09PagedCaptureHold('natural final Core observation target installation/Authority differs')
        # Foreign namespaces receive the same codec/hash/key validation and remain exact;
        # this inventory never borrows their original as the selected target's authority.
    elif table=='authority_owner_paid_guard_observations_v3':
        from .v3_owner_paid_guard_observation import COLUMNS,validate_owner_paid_guard_observation_row_v3
        if (tuple(columns)!=COLUMNS or shape.columns!=COLUMNS or shape.primary_key_columns!=COLUMNS[:4]
                or shape.primary_key_types!=('text','text','text','text')):
            raise C09PagedCaptureHold('paid Owner guard original exact Source row/PK differs')
        value=validate_owner_paid_guard_observation_row_v3(tuple(row))
        from .c09_pre_graph_core_dependency_source_v3 import require_final_core_pre_graph_observation_retention_v3
        from ..runtime.c09_paged_sql_v2 import current_c09_sql_meter_v2
        require_final_core_pre_graph_observation_retention_v3(transform.basis.session,transform.pair,value,tuple(row),
            meter=current_c09_sql_meter_v2())
        if value.authority_namespace==transform.scope.authority_namespace and (
                value.guard.authority_id!=transform.scope.authority_id
                or value.guard.installation_id!=transform.scope.installation_id):
            raise C09PagedCaptureHold('paid Owner guard original target installation/Authority differs')
    elif table in legacy._HABIT_CORE_TABLES:
        from .c09_habit_policy_rows_v1 import validate_habit_core_row_v1,_installed_v1
        config,control=_installed_v1(transform)
        validate_habit_core_row_v1(table,columns,row,config=config,control=control)
    elif table==legacy._CONTACT_POLICY_TABLE:
        from .c09_contact_policy_rows_v1 import validate_contact_policy_core_row_v1
        validate_contact_policy_core_row_v1(columns,row)
    elif table==legacy._D07_TIMING_TABLE:
        legacy.validate_d07_timing_row_v1(columns,row)
    elif table==legacy._MODEL_BUDGET_TABLE:
        legacy.validate_c09_model_budget_row_v1(columns,row)
    elif table==legacy._CONTACT_FINISH_TABLE:
        legacy.validate_contact_finish_row_v1(columns,row)
    elif table==legacy._CONTACT_FRAME_AUTH_TABLE:
        legacy.validate_contact_frame_authentication_row_v1(columns,row)
    elif table==legacy._LIFE_COMPLETED_ARCHIVE_TABLE:
        legacy.validate_life_archive_row_v1(columns,row)
    elif table in legacy._PACKAGE_CORE_SCHEMAS:
        legacy.validate_d12_package_core_row_v2(table,columns,row)
        if table=='authority_d12_package_heads_v2' and row[0]==transform.scope.authority_namespace and row[4] not in {'active','rollback_complete'}:
            raise C09PagedCaptureHold('unfinished package operation remains authoritative')
    elif table in legacy._INSTALLER_GENESIS_TABLES:
        legacy.validate_installer_genesis_row_v1(table,columns,row)
    elif table in legacy._OWNER_PAIRING_SCHEMAS:
        legacy.validate_owner_pairing_row_v1(table,columns,row,authority_id=transform.scope.authority_id)
    elif table not in legacy._KNOWN_CORE_TABLES and table not in MANAGED_DDLS_V2:
        # New facts/issue tables must have the actual producer's registered codec.
        transform.facts.require_registered_core_row(table,columns,row,meter=meter)



def _bootstrap_quantum(builder,budget,position):
    from ..runtime.c09_paged_sql_v2 import CAPTURE_DDLS_V2,CAPTURE_TRIGGERS_V2
    pair=builder.pair;meter=C09AuthorityRowMeterV2(budget.max_bytes);started=monotonic_ns()
    # This is a fixed installed schema catalogue, never a collection of facts.
    objects=[('table','authority_c09_role_build_v2',STATE_DDL)]
    objects.extend(('table',name,ddl) for name,ddl in CAPTURE_DDLS_V2.items())
    objects.extend(('trigger',name,ddl) for name,ddl in CAPTURE_TRIGGERS_V2)
    objects.extend(('table',name,ddl) for name,ddl in MANAGED_DDLS_V2.items() if name!='authority_c09_role_build_v2')
    if builder.transform.role=='core':
        objects.extend(('table',name,ddl) for name,ddl in (
            ('authority_c09_consumed_execution_v1',legacy._LEDGER_DDL),
            ('authority_c09_unresolved_effects_v1',legacy._EFFECT_DDL),
            ('authority_c09_originals_archive_v1',ARCHIVE_DDL),
            ('authority_c09_deletion_continuations_v1',CONTINUATION_DDL),
            (D13_RETIREMENT_TABLE,D13_RETIREMENT_DDL)))
        objects.extend(('trigger',name,ddl) for name,ddl in D13_RETIREMENT_TRIGGERS.items())
    index=position.get('index',0);done=0
    with capture_transaction_v2(pair.candidate):
        while index<len(objects) and done<budget.max_records and monotonic_ns()-started<budget.max_local_ns:
            kind,name,ddl=objects[index]
            found=meter.read_one(pair.candidate,'sqlite_master',('sql',),'type=? AND name=?',(kind,name))
            if found is None: meter.write(pair.candidate,ddl)
            elif found!=(ddl,): raise C09PagedCaptureHold('registered authority capture DDL differs')
            index+=1;done+=1
        if index==len(objects):
            phase='schema_census'
            position={'after':None,'count':0,'chain':canonical_digest(('sylanne3.c09.authority-schema-census.v2',builder.scope.scope_digest,builder.transform.role))}
        else: phase='bootstrap';position={'index':index}
        _save_position(pair,builder.scope,phase,position,meter)
    return _progress(builder.transform,phase,done,meter,started)


def _position(pair,scope,meter):
    row=meter.read_one(pair.candidate,'authority_c09_role_build_v2',
        ('phase','position_json'),'scope_digest=? AND role=?',(scope.scope_digest,scope_role(pair)))
    if row is None: return 'schema_census',{'after':None,'count':0,'chain':canonical_digest(('sylanne3.c09.authority-schema-census.v2',scope.scope_digest,scope_role(pair)))}
    if len(row[1].encode('utf-8'))>65536: raise C09PagedCaptureHold('authority role descriptor exceeds installed bound')
    return row[0],json.loads(row[1])


def _save_position(pair,scope,phase,position,meter):
    wire=_json(position)
    if len(wire.encode('utf-8'))>65536: raise C09PagedCaptureHold('authority role cursor exceeds descriptor')
    meter.write(pair.candidate,"INSERT INTO authority_c09_role_build_v2 VALUES(?,?,?,?) ON CONFLICT(scope_digest,role) DO UPDATE SET phase=excluded.phase,position_json=excluded.position_json",
        (scope.scope_digest,scope_role(pair),phase,wire))


def _stream(pair,scope,shape,kind,family=None):
    from ..runtime.c09_logical_source_v3 import C09LogicalSourceShapeV3
    physical=shape.physical_shape if type(shape) is C09LogicalSourceShapeV3 else shape
    digest=shape.logical_shape_digest if type(shape) is C09LogicalSourceShapeV3 else shape.schema_digest
    return C09StreamIdentityV2(scope.scope_digest,pair.source_original.role_source_digest,
        kind,family or physical.table,digest,physical.primary_key_columns,physical.primary_key_types)


def _schema_stream(pair,scope):
    return C09StreamIdentityV2(scope.scope_digest,pair.source_original.role_source_digest,
        'schema_catalogue','authority_sql_schema_v2',pair.source_original.schema_root,
        ('object_type','object_name'),('text','text'))


def _schema_metadata(source,after,meter):
    last=tuple(after) if after is not None else ('','')
    row=source.execute("SELECT type,name,tbl_name,length(CAST(sql AS BLOB)) FROM sqlite_master WHERE sql IS NOT NULL AND name NOT GLOB 'sqlite_*' AND (type COLLATE BINARY>? OR (type COLLATE BINARY=? AND name COLLATE BINARY>?)) ORDER BY type COLLATE BINARY,name COLLATE BINARY LIMIT 1",(last[0],last[0],last[1])).fetchone()
    meter.charge_read(len(canonical_serialize(row).encode('utf-8')))
    if row is not None and row[0] not in {'table','index','trigger'}:
        raise C09PagedCaptureHold('unregistered schema object kind')
    return row


def _verify_schema(transform,original,meter):
    pair=transform.pair
    table=original.table_name
    if transform.role=='core':
        from .d13_core_counter_service_v1 import _SCHEMA as COUNTER_DDL
        from .d13_provider_http_admission_v1 import SCHEMA as HTTP_DDL
        originals={'authority_d13_counter_originals_v1':COUNTER_DDL,'authority_d13_provider_http_bindings_v1':HTTP_DDL}
        if table=='authority_natural_final_observations_v4':
            from .v2_execution_bridge import NATURAL_FINAL_OBSERVATION_DDL_MAP_V4
            expected=NATURAL_FINAL_OBSERVATION_DDL_MAP_V4.get(original.name)
            expected_kind='table' if original.name==table else 'trigger'
            if expected is None or original.object_type!=expected_kind or original.sql!=expected:
                raise C09PagedCaptureHold('registered natural final Core observation table/immutable trigger differs')
            # Metadata reads are charged to this existing schema quantum, never a new lease.
            for name,ddl in NATURAL_FINAL_OBSERVATION_DDL_MAP_V4.items():
                kind='table' if name==table else 'trigger'
                row=meter.read_one(pair.source,'sqlite_master',('tbl_name','sql'),'type=? AND name=?',(kind,name))
                if row!=(table,ddl):
                    raise C09PagedCaptureHold('actual natural final Core observation table and both immutable triggers required')
        elif table=='authority_owner_paid_guard_observations_v3':
            from .v3_owner_paid_guard_observation import TABLE,DDL_MAP
            kind='table' if original.name==TABLE else 'trigger'
            expected=DDL_MAP.get(original.name)
            if expected is None or original.object_type!=kind or original.sql!=expected:
                raise C09PagedCaptureHold('actual immutable paid Owner guard Source schema object differs')
            for name,ddl in DDL_MAP.items():
                object_kind='table' if name==TABLE else 'trigger'
                row=meter.read_one(pair.source,'sqlite_master',('tbl_name','sql'),'type=? AND name=?',(object_kind,name))
                if row!=(TABLE,ddl):
                    raise C09PagedCaptureHold('actual paid Owner guard table and immutable triggers required')
        elif table in originals:
            if original.object_type=='table':
                from ..segmented_sql_cell_v1 import CORE_REF_DDLS_V2
                expected=CORE_REF_DDLS_V2[table] if original.sql==CORE_REF_DDLS_V2[table] else originals[table]
            elif original.object_type=='trigger':
                if table=='authority_d13_counter_originals_v1':
                    triggers={'authority_d13_counter_no_'+op.lower()+'_v1':
                        'CREATE TRIGGER authority_d13_counter_no_'+op.lower()+'_v1 BEFORE '+op+' ON '+table+" BEGIN SELECT RAISE(ABORT,'Core counter original is immutable'); END" for op in ('UPDATE','DELETE')}
                else:
                    triggers={'d13_provider_http_no_'+op.lower()+'_v1':
                        'CREATE TRIGGER d13_provider_http_no_'+op.lower()+'_v1 BEFORE '+op+' ON '+table+" BEGIN SELECT RAISE(ABORT,'provider HTTP binding original is immutable'); END" for op in ('UPDATE','DELETE')}
                expected=triggers.get(original.name)
            else:expected=None
            if expected is None or original.sql!=expected:
                raise C09PagedCaptureHold('registered D13 Core source table/immutable trigger differs')
        elif table=='authority_migration_snapshot_certificate_members_v1':
            from .migration_snapshot_certificate_members_v1 import _OBJECTS as MEMBER_OBJECTS
            expected=MEMBER_OBJECTS.get(original.primary_key)
            if expected is None or original.sql!=expected:
                raise C09PagedCaptureHold('actual migration certificate member Source schema differs')
            for (kind,name),ddl in MEMBER_OBJECTS.items():
                row=meter.read_one(pair.source,'sqlite_master',('tbl_name','sql'),'type=? AND name=?',(kind,name))
                if row!=(table,ddl):
                    raise C09PagedCaptureHold('actual migration certificate member table/index/immutable triggers required')
        elif table in legacy._HABIT_CORE_TABLES:
            from .c09_habit_policy_rows_v1 import validate_habit_schema_object_v1
            validate_habit_schema_object_v1(transform,original,meter)
        elif table==D13_RETIREMENT_TABLE:
            expected=D13_RETIREMENT_DDL if original.object_type=='table' else D13_RETIREMENT_TRIGGERS.get(original.name)
            if original.sql!=expected:raise C09PagedCaptureHold('actual immutable D13 retirement Source schema differs')
        elif table not in legacy._KNOWN_CORE_TABLES and table not in MANAGED_DDLS_V2:
            from ..runtime_storage_v3 import selected_runtime_catalogue_v3
            from ..segmented_sql_cell_v1 import DDLS as SOURCE_DDLS,TRIGGERS as SOURCE_TRIGGERS
            catalogue={(kind,name):ddl for kind,name,ddl in selected_runtime_catalogue_v3('core')}
            catalogue.update({('table',name):ddl for name,ddl in SOURCE_DDLS.items()})
            catalogue.update({('trigger',name):ddl for name,ddl in SOURCE_TRIGGERS.items()})
            expected=catalogue.get(original.primary_key)
            if expected is not None:
                if original.sql!=expected:raise C09PagedCaptureHold('actual registered segmented Core Source schema differs')
            else:transform.facts.require_registered_core_schema(original)
    elif transform.role=='execution':
        if table not in _EXECUTION_TABLES: raise C09PagedCaptureHold('unknown execution schema')
    elif table not in legacy._KNOWN_DELETION_TABLES:
        raise C09PagedCaptureHold('unknown deletion schema')
    if original.object_type=='table':
        expected = (
            legacy._OWNER_PAIRING_SCHEMAS.get(table)
            or legacy._INSTALLER_GENESIS_TABLES.get(table)
            or legacy._PACKAGE_CORE_SCHEMAS.get(table)
            or MANAGED_DDLS_V2.get(table))
        if expected is not None and original.sql!=expected:
            raise C09PagedCaptureHold('registered fixed table DDL differs: '+table)
    # SQL comes from the sealed source handle, never from a request.
    row=pair.source.execute("SELECT tbl_name,sql FROM sqlite_master WHERE type=? AND name=?",original.primary_key).fetchone()
    if row!=(original.table_name,original.sql): raise C09PagedCaptureHold('source schema changed during capture')


def _target_schema_sql(transform,original):
    if transform.role=='core' and original.object_type=='table':
        from ..segmented_sql_cell_v1 import CORE_REF_DDLS_V2
        if original.name in CORE_REF_DDLS_V2:
            from .d13_core_counter_service_v1 import _SCHEMA as COUNTER_SOURCE_DDL
            from .d13_provider_http_admission_v1 import SCHEMA as HTTP_SOURCE_DDL
            source=COUNTER_SOURCE_DDL if original.name=='authority_d13_counter_originals_v1' else HTTP_SOURCE_DDL
            if original.sql not in (source,CORE_REF_DDLS_V2[original.name]):raise C09PagedCaptureHold('registered actual Core source physical schema differs before reference mapping')
            return CORE_REF_DDLS_V2[original.name]
    if transform.role=='execution' and original.object_type=='table' and original.name=='authority_v2_execution_redacted_prefix_v4':
        from .v2_execution_journal import _PREFIX_DDL_V4
        return _PREFIX_DDL_V4
    return original.sql


def _schema_quantum(transform,budget,phase,position):
    """Independent metadata census, followed by exact schema-body capture."""
    from ..runtime.c09_paged_capture_contract_v2 import (
        C09CaptureRecordV2,C09CountOriginalV2,append_c09_page_v2,
        c09_paged_value_to_wire_v2,meter_c09_commitments_v2)
    pair,scope=transform.pair,transform.scope
    meter=C09AuthorityRowMeterV2(budget.max_bytes)
    started=monotonic_ns(); count=0; eof=False
    stream=_schema_stream(pair,scope)
    pair.check_source()
    with capture_transaction_v2(pair.candidate):
        cursor=begin_capture_stream_v2(pair.candidate,stream)
        records=[]
        pair.source.execute('BEGIN'); read_started=monotonic_ns()
        try:
            with meter_c09_commitments_v2(meter):
                while count<budget.max_records and monotonic_ns()-started<budget.max_local_ns:
                    if meter.remaining_bytes<8192: break
                    found=_schema_metadata(pair.source,position['after'],meter)
                    if found is None: eof=True;break
                    key=found[:2]
                    if phase=='schema_census':
                        position['chain']=canonical_digest(('sylanne3.c09.authority-schema-census-row.v2',
                            position['chain'],position['count']+1,found))
                        position['count']+=1
                    else:
                        # Reserve worst-case SQL/copies and proof descriptor before loading.
                        if found[3]*8+8192>meter.remaining_bytes:
                            if not records: raise C09PagedCaptureHold('schema object requires bounded continuation codec')
                            break
                        original=read_c09_next_schema_object_v2(pair.source,tuple(position['after']) if position['after'] is not None else None,max_bytes=meter.remaining_bytes)
                        _verify_schema(transform,original,meter)
                        meter.charge_read(len(original.sql.encode('utf-8')))
                        target_sql=_target_schema_sql(transform,original)
                        values=(scope.scope_digest,transform.role,*original.primary_key,original.table_name,
                            original.sql,target_sql,original.commitment)
                        _same_insert(pair.candidate,'authority_c09_role_schema_v2',
                            ('scope_digest','role','object_type','object_name','table_name','source_sql','target_sql','source_commitment'),
                            values,('scope_digest','role','object_type','object_name'),meter)
                        if original.object_type=='table':
                            rewritten=replace(original,sql=target_sql)
                            # Fixed prefix upgrade is a registered producer; other DDL is exact.
                            apply_c09_schema_object_v2(pair.candidate,rewritten,verify_installed_object=lambda obj: _verify_target_schema(transform,original,obj,meter))
                            meter.charge_write(len(target_sql.encode('utf-8')))
                        records.append(C09CaptureRecordV2(original.primary_key,original.commitment))
                    position['after']=list(key);count+=1
        finally: pair.source.rollback()
        read_ns=monotonic_ns()-read_started
        if read_ns>budget.max_read_ns: raise C09PagedCaptureHold('schema source transaction exceeded installed duration')
        if phase=='schema_census' and eof:
            observed=canonical_digest(('sylanne3.c09.authority-schema-census-eof.v2',stream.stream_id,position))
            original_digest=canonical_digest(('sylanne3.c09.authority-schema-count.v2',stream.stream_id,position,observed))
            census=C09CountOriginalV2(stream.stream_id,position['count'],tuple(position['after']) if position['after'] is not None else None,
                observed,'c09-schema-count-v2:'+original_digest,original_digest)
            meter.write(pair.candidate,"UPDATE c09_capture_progress_v2 SET progress_json=? WHERE stream_id=? AND phase='census'",
                (_json({'count':position['count'],'last_key':position['after'],'chain':position['chain'],'eof':observed,'original':c09_paged_value_to_wire_v2(census)}),stream.stream_id))
            phase='schema_capture';position={'after':None}
        elif phase=='schema_capture':
            if records:
                page=append_c09_page_v2(stream,cursor,tuple(records))
                page_wire=_json(asdict(page));records_wire=_json([asdict(row) for row in records])
                meter.write(pair.candidate,'INSERT INTO c09_capture_pages_v2 VALUES(?,?,?,?)',
                    (stream.stream_id,page.page_index,page_wire,records_wire))
                for offset,record in enumerate(records,1):
                    meter.write(pair.candidate,'INSERT INTO c09_capture_members_v2 VALUES(?,?,?,?,?,?)',
                        (stream.stream_id,cursor.record_offset+offset,canonical_digest(record.primary_key),
                         canonical_serialize(record.primary_key),record.commitment,page.page_index))
                cursor=page.next_cursor
            data_eof=canonical_digest(('sylanne3.c09.authority-schema-data-eof.v2',stream.stream_id,cursor.record_offset,cursor.last_key)) if eof else None
            meter.write(pair.candidate,"UPDATE c09_capture_progress_v2 SET progress_json=? WHERE stream_id=? AND phase='data'",
                (_json({'cursor':asdict(cursor),'eof':data_eof}),stream.stream_id))
            if eof: phase='schema_seal';position={}
        _save_position(pair,scope,phase,position,meter)
    pair.check_source()
    return _progress(transform,phase,count,meter,started,read_ns)


def _progress(transform,phase,records,meter,started,read_ns=0):
    elapsed=monotonic_ns()-started
    return dict(status='progress',role=transform.role,phase=phase,
        completed_records=records,actual_io_bytes=meter.related_read_bytes+meter.target_write_bytes,
        local_ns=elapsed,read_transaction_ns=read_ns,
        resource_quantum_within_limit=elapsed<=25000000 and read_ns<=250000000)


def _next_table(pair,scope,after,meter):
    return meter.read_one(pair.candidate,'authority_c09_role_schema_v2',
        ('object_name',),"scope_digest=? AND role=? AND object_type='table' AND object_name COLLATE BINARY>? ORDER BY object_name COLLATE BINARY ASC",
        (scope.scope_digest,scope_role(pair),after or ''))


def _persist_stream(pair,scope,table,kind,stream,meter,seal=None):
    identity=_json(asdict(stream))
    saved=meter.read_one(pair.candidate,'authority_c09_role_streams_v2',
        ('stream_json','seal_json'),'scope_digest=? AND role=? AND table_name=? AND stream_kind=?',
        (scope.scope_digest,scope_role(pair),table,kind))
    wire=None if seal is None else _json(asdict(seal))
    if saved is None:
        meter.write(pair.candidate,'INSERT INTO authority_c09_role_streams_v2 VALUES(?,?,?,?,?,?)',
            (scope.scope_digest,scope_role(pair),table,kind,identity,wire))
    elif saved[0]!=identity or saved[1] is not None and saved[1]!=wire:
        raise C09PagedCaptureHold('role stream directory original conflicts')
    elif seal is not None:
        meter.write(pair.candidate,'UPDATE authority_c09_role_streams_v2 SET seal_json=? WHERE scope_digest=? AND role=? AND table_name=? AND stream_kind=?',
            (wire,scope.scope_digest,scope_role(pair),table,kind))


def _verify_target_schema(transform,original,target,meter):
    _verify_schema(transform,original,meter)
    if (target.object_type,target.name,target.table_name,target.sql)!=(
        original.object_type,original.name,original.table_name,_target_schema_sql(transform,original)):
        raise C09PagedCaptureHold('unregistered schema rewrite')


def _suffix_transform(transform,execution_pair,*,readonly=False):
    """Validate and consume each original suffix entry without retaining body."""
    def apply(db,shape,key,row,remaining):
        from .v2_contract import PendingMutationV2,decode_bytes
        meter=(_ReadOnlyAuthorityRowMeterV2 if readonly else C09AuthorityRowMeterV2)(remaining)
        transform.origin=('execution_row',shape.table,_json(key))
        if shape.columns!=('seq','mutation_id','request_digest','append_id','pending','previous_digest','chain_digest'):
            raise C09PagedCaptureHold('execution suffix columns differ')
        encoded=row[4]
        if type(encoded) is not bytes: raise C09PagedCaptureHold('execution suffix pending bytes differ')
        namespace=transform.scope.authority_namespace
        binding=None;pending=None
        from .d04_root_execution_journal_v3 import ROOT_ENTRY_PREFIX_V3
        from .d04_numeric_journal_v3 import ENTRY_PREFIX
        from .d04_root_execution_contract_v3 import D04RootExecutionBindingV3,root_execution_from_wire_v3
        from .d04_numeric_contract_v3 import D04NumericBindingV3,from_wire as numeric_from_wire
        if encoded.startswith(ROOT_ENTRY_PREFIX_V3):
            binding=root_execution_from_wire_v3(json.loads(encoded)['d04_root_execution_original']['binding'],D04RootExecutionBindingV3)
        elif encoded.startswith(ENTRY_PREFIX):
            binding=numeric_from_wire(json.loads(encoded)['d04_numeric_original']['binding'],D04NumericBindingV3)
        elif encoded.startswith(b'{"d04_series_original":'):
            from .d04_series_contract_v1 import D04SeriesChunkBindingV1,from_wire
            binding=from_wire(json.loads(encoded)['d04_series_original']['binding'],D04SeriesChunkBindingV1).numeric
        elif encoded.startswith(b'{"d11_life_original":'):
            from ..runtime.d11_life_contract_v1 import D11LifeExecutionBindingV1,life_from_wire_v1
            binding=life_from_wire_v1(json.loads(encoded)['d11_life_original']['binding'],D11LifeExecutionBindingV1)
        elif encoded.startswith(b'{"d11_offline_tick_original":'):
            from .d11_offline_tick_contract_v1 import D11OfflineTickBindingV1,offline_tick_from_wire_v1
            binding=offline_tick_from_wire_v1(json.loads(encoded)['d11_offline_tick_original']['binding'],D11OfflineTickBindingV1)
        elif encoded.startswith(b'{"binding":'):
            from .internal_work_contract import InternalWorkBindingV1
            binding=InternalWorkBindingV1(**json.loads(encoded)['binding'])
        else:
            pending=decode_bytes(encoded)
            if type(pending) is not PendingMutationV2 or pending.permit.namespace!=namespace:
                raise C09PagedCaptureHold('execution pending identity differs')
        if binding is not None:
            if binding.authority_namespace!=namespace: raise C09PagedCaptureHold('execution binding namespace differs')
            operation,execution_id=binding.operation_id,binding.execution_id
        else:
            operation,execution_id=pending.permit.operation_id,pending.permit.effect_id
        fact=transform.facts.lookup_execution(execution_id,meter=meter)
        if execution_id is None or fact is None: raise C09PagedCaptureHold('execution entry lacks authenticated fact')
        # Historical fact and exact journal source are independently bound by the resolver.
        transform.facts.require_execution_journal_row(execution_pair.source_original,shape.columns,row,meter=meter)
        transform._consume('journal_mutation',row[1],operation,legacy._row_commitment(shape.table,shape.columns,row),meter)
        transform._consume('journal_append',row[3],operation,sha256(encoded).hexdigest(),meter)
        transform._consume('execution_id',execution_id,operation,fact.input_commitment,meter)
        if binding is not None:
            transform._consume('internal_operation',operation,operation,
                binding.digest if not encoded.startswith(b'{"binding":') else binding.binding_digest,meter)
        else:
            columns=('scope_digest','execution_id','execution_seq','operation_id','mutation_id','phase','chain_digest')
            values=(transform.scope.scope_digest,execution_id,row[0],operation,pending.mutation_id,pending.phase,row[6])
            prior=meter.read_one(db,'authority_c09_execution_latest_v2',columns,'scope_digest=? AND execution_id=?',values[:2])
            if readonly:
                if prior is None or prior[2]<row[0] or prior[2]==row[0] and prior!=values:
                    raise C09PagedCaptureHold('cold latest execution index differs from original')
            elif prior is None:
                meter.write(db,'INSERT INTO authority_c09_execution_latest_v2 VALUES(?,?,?,?,?,?,?)',values)
            elif prior[2]<row[0]:
                meter.write(db,'UPDATE authority_c09_execution_latest_v2 SET execution_seq=?,operation_id=?,mutation_id=?,phase=?,chain_digest=? WHERE scope_digest=? AND execution_id=?',
                    (*values[2:],*values[:2]))
            elif prior!=values:
                raise C09PagedCaptureHold('execution suffix key order or identity conflicts')
        digest=canonical_digest(('sylanne3.c09.authority-execution-consumption.v2',execution_pair.source_original.role_source_digest,
            key,legacy._row_commitment(shape.table,shape.columns,row),fact.input_commitment,transform.completion.pin_digest))
        meter.charge_encode(len(canonical_serialize((key,digest)).encode('utf-8')))
        return C09RowTransformResultV2(digest,meter.related_read_bytes,meter.target_write_bytes)
    return apply


def _finish_unknown_effect(transform,shape,row,meter):
    if row[shape.columns.index('namespace')]!=transform.scope.authority_namespace or row[shape.columns.index('state')]!='unresolved':
        return
    effect=row[shape.columns.index('effect_id')]
    unknown=transform.facts.lookup_unknown(effect,meter=meter)
    if unknown is None: raise C09PagedCaptureHold('unresolved effect lacks original UNKNOWN footprint')
    latest=meter.read_one(transform.pair.candidate,'authority_c09_execution_latest_v2',
        ('execution_seq','operation_id','mutation_id','phase','chain_digest'),
        'scope_digest=? AND execution_id=?',(transform.scope.scope_digest,effect))
    columns=('namespace','effect_id','operation_id','mutation_id','phase','execution_seq','append_digest','footprint_commitment','conflict_keys_digest')
    footprint=canonical_digest(unknown.footprint)
    if latest is None:
        prior=meter.read_one(transform.pair.candidate,'authority_c09_unresolved_effects_v1',columns,
            'namespace=? AND effect_id=?',(transform.scope.authority_namespace,effect))
        if prior is None or (prior[2],prior[7])!=(unknown.footprint.operation_id,footprint):
            raise C09PagedCaptureHold('historical unresolved footprint original absent')
        return
    if latest[3] not in {'claimed','observed'} or (latest[0],latest[1])!=(
        row[shape.columns.index('execution_seq')],unknown.footprint.operation_id):
        raise C09PagedCaptureHold('unresolved effect sequence/phase differs')
    value=(transform.scope.authority_namespace,effect,latest[1],latest[2],latest[3],latest[0],latest[4],footprint,
           legacy._digest(row[shape.columns.index('conflict_keys_json')]))
    prior=meter.read_one(transform.pair.candidate,'authority_c09_unresolved_effects_v1',columns,
        'namespace=? AND effect_id=?',value[:2])
    if prior is not None and prior!=value: raise C09PagedCaptureHold('unresolved retained ledger original conflicts')
    if prior is None:
        meter.write(transform.pair.candidate,'INSERT INTO authority_c09_unresolved_effects_v1 VALUES(?,?,?,?,?,?,?,?,?)',value)
        _generated(transform.pair,transform.scope,'authority_c09_unresolved_effects_v1',columns,value,
                   'verified_unknown_footprint_v2',footprint,meter)


def _finish_execution_generated(transform,meter):
    from .v2_execution_journal import _OBJECTS_V4
    pair=transform.pair
    for (kind,name),ddl in _OBJECTS_V4.items():
        existing=meter.read_one(pair.candidate,'sqlite_master',('sql',),'type=? AND name=?',(kind,name))
        if existing is None: meter.write(pair.candidate,ddl)
        elif existing!=(ddl,): raise C09PagedCaptureHold('execution installed prefix DDL differs')
    shape=read_c09_table_shape_v2(pair.candidate,'authority_v2_execution_redacted_prefix_v4')
    values=(1,transform.scope.authority_id,transform.scope.authority_namespace,transform.scope.operation_id,
        transform.completion.old_journal_id,transform.completion.old_seq,transform.completion.old_digest,
        transform.completion.pin_digest,transform.basis.graph_issue_digest,pair.build_plan['new_execution_journal_id'])
    if _same_insert(pair.candidate,shape.table,shape.columns,values,shape.primary_key_columns,meter):
        _generated(pair,transform.scope,shape.table,shape.columns,values,'journal_prefix_v4',
                   transform.completion.pin_digest,meter)
    shape=read_c09_table_shape_v2(pair.candidate,'authority_v2_execution_meta')
    current=meter.read_one(pair.candidate,shape.table,shape.columns,'key=?',('core_redaction_source',))
    if current is not None and current!=('core_redaction_source',transform._execution_core_source()):
        raise C09PagedCaptureHold('journal Core source marker differs')
    if current is None:
        values=('core_redaction_source',transform._execution_core_source())
        meter.write(pair.candidate,'INSERT INTO authority_v2_execution_meta VALUES(?,?)',values)
        _generated(pair,transform.scope,shape.table,shape.columns,values,'journal_core_source_v4',
                   transform.basis.graph_issue_digest,meter)
    for key in ('namespace','journal_id','schema_version'):
        values=meter.read_one(pair.candidate,shape.table,shape.columns,'key=?',(key,))
        expected={'namespace':transform.scope.authority_namespace,'journal_id':pair.build_plan['new_execution_journal_id'],'schema_version':'4'}[key]
        if values!=(key,expected): raise C09PagedCaptureHold('generated journal metadata is incomplete')


def _finish_continuation_generated(transform,meter):
    from .c09_storage_control_v1 import canonical,digest
    permit=transform._active_deletion_permit(meter)
    if permit is None: return
    continuation=transform._continuation(permit,meter)
    accepted=transform.basis.accepted_receipt
    body=dict(authority_id=transform.scope.authority_id,installation_id=transform.scope.installation_id,
        namespace=transform.scope.authority_namespace,operation_id=transform.scope.operation_id,
        old_manifest_digest=transform.scope.old_manifest_digest,maintenance_generation=transform.scope.maintenance_generation,
        accepted_receipt_digest=canonical_digest(accepted),original_fence_permit_digest=canonical_digest(permit),
        before_anchor=asdict(accepted.after_anchor),after_anchor=asdict(continuation.pinned_anchor),
        continuation_permit=asdict(continuation))
    transition={**body,'transition_digest':digest(body)}
    columns=('namespace','operation_id','transition_json','transition_digest')
    values=(transform.scope.authority_namespace,transform.scope.operation_id,canonical(transition),transition['transition_digest'])
    if _same_insert(transform.pair.candidate,'authority_c09_deletion_continuations_v1',columns,values,columns[:2],meter):
        _generated(transform.pair,transform.scope,'authority_c09_deletion_continuations_v1',columns,values,
                   'accepted_deletion_continuation_v1',transform.scope.accepted_receipt_digest,meter)


_BUILDER_TOKEN=object()






def _read_d13_core_metadata_v3(builder,table,key,meter,*,required=True):
    """Bounded actual historical metadata only; large draft needs its stream codec."""
    shape=_table_shape(builder.pair.source,table)
    where=' AND '.join(_q(name)+'=?' for name in shape.primary_key_columns)
    if 'payload_cell_id' in shape.columns:
        from ..segmented_sql_cell_v1 import CORE_REF_DDLS_V2
        actual=meter.read_fixed_row(builder.pair.source,'sqlite_master',('sql',),'type=? AND name=?',('table',table))
        if actual!=(CORE_REF_DDLS_V2.get(table),):raise C09PagedCaptureHold('actual bounded D13 metadata physical schema differs')
        row=meter.read_fixed_row(builder.pair.source,table,(*shape.primary_key_columns,'payload_cell_id','payload_digest'),where,key)
        if row is None:
            if required:raise C09PagedCaptureHold('actual D13 historical metadata phase is absent')
            return None
        scope=builder.session.begin_source_physical_read_v3(builder.pair,meter=meter)
        header=scope.read_cell_header_v3(row[3],meter=meter)
        if header[1]!='canonical-json.ascii.v1' or header[4]>65536 or header[6]!=row[4]:
            raise C09PagedCaptureHold('actual D13 metadata needs its registered bounded canonical payload/header commitment')
        meter.require_available(header[4]*8+131072)
        if sum(value._source_heap_bytes() for value in scope.arena)+header[4]*8+65536>meter.budget.reserved_arena_bytes:
            raise C09PagedCaptureHold('actual bounded D13 metadata/copies exceed the same Root reserved arena')
        payload,total=scope.read_cell_fragment_v3(row[3],start=0,length=min(header[4],16384),meter=meter)
        fragments=[payload];offset=len(payload)
        while offset<total:
            block,observed=scope.read_cell_fragment_v3(row[3],start=offset,length=min(16384,total-offset),meter=meter)
            if observed!=total or not block:raise C09PagedCaptureHold('actual bounded metadata original fragment disappeared')
            fragments.append(block);offset+=len(block)
        if total!=header[4] or offset!=total:raise C09PagedCaptureHold('actual D13 metadata original complete length differs')
        payload=b''.join(fragments)
        if sha256(payload).hexdigest()!=row[4]:raise C09PagedCaptureHold('actual D13 metadata immutable complete raw digest differs')
        row=(*row[:3],payload.decode('ascii'),row[4])
    else:
        row=meter.read_fixed_row(builder.pair.source,table,shape.columns,where,key)
        if row is None:
            if required:raise C09PagedCaptureHold('actual D13 historical metadata phase is absent')
            return None
    row=tuple(row)
    if tuple(row[:3])!=key or sha256(row[3].encode('utf-8')).hexdigest()!=row[4]:
        raise C09PagedCaptureHold('actual D13 historical metadata PK/complete byte digest differs')
    from .c09_model_budget_original_v1 import _json
    value=_json(row[3])
    return value,row




def _d13_frozen_graph_pair_v3(builder):
    from .c09_role_capture_pair_v2 import InstalledC09RolePairV2
    producer=builder.session._control._role_pairs.get('graph')
    if producer is None or type(producer.pair) is not InstalledC09RolePairV2:
        raise C09PagedCaptureHold('D13 historical accounting requires actual frozen Graph role source')
    pair=producer.pair
    if pair._producer.session is not builder.session or pair.source_original.scope_digest!=builder.scope.scope_digest:
        raise C09PagedCaptureHold('D13 historical Graph originals crossed actual capture scope')
    pair.require_current()
    return pair


def _read_d13_graph_atom_metadata_v3(builder,token,meter):
    """Small original atom content from its actual registered physical Source."""
    pair=_d13_frozen_graph_pair_v3(builder);namespace=builder.session._control.maintenance.namespace_id
    shape=read_c09_table_shape_v2(pair.source,'graph_atoms',meter=meter)
    if 'value_cell_id' not in shape.columns:
        return meter.read_fixed_row(pair.source,'graph_atoms',('revision','value','valid'),
            'token=? AND bot=? AND persona=?',(token,*namespace.as_tuple))
    from ..segmented_sql_cell_v1 import GRAPH_REF_DDLS_V3
    actual=meter.read_fixed_row(pair.source,'sqlite_master',('sql',),'type=? AND name=?',('table','graph_atoms'))
    if actual!=(GRAPH_REF_DDLS_V3['graph_atoms'],):raise C09PagedCaptureHold('actual D13 Graph atom physical Source schema differs')
    row=meter.read_fixed_row(pair.source,'graph_atoms',('revision','value_cell_id','valid'),
        'token=? AND bot=? AND persona=?',(token,*namespace.as_tuple))
    if row is None:return None
    scope=builder.session.begin_source_physical_read_v3(pair,meter=meter);header=scope.read_cell_header_v3(row[1],meter=meter)
    if header[1] not in {'canonical-json.ascii.v1','canonical-json.utf8.v1'} or not 0<header[4]<=65536:
        raise C09PagedCaptureHold('actual D13 accounting atom needs its registered small-content Source profile')
    if sum(value._source_heap_bytes() for value in scope.arena)+header[4]*8+65536>meter.budget.reserved_arena_bytes:
        raise C09PagedCaptureHold('actual accounting atom bytes/decode copies exceed the caller reserved Source arena')
    parts=[];offset=0;digest=sha256();root=canonical_digest(('sylanne3.segmented-cell-genesis.v1',row[1]))
    for ordinal in range(header[5]):
        segment=scope.read_cell_segment_v3(row[1],ordinal,meter=meter)
        if segment is None or segment[0]!=offset:raise C09PagedCaptureHold('actual accounting atom ordered Source segments differ')
        block=segment[1];parts.append(block);digest.update(block)
        root=canonical_digest(('sylanne3.segmented-cell-link.v1',root,row[1],ordinal,offset,len(block),segment[2]));offset+=len(block)
    scope.require_cell_eof_v3(row[1],header[5],meter=meter)
    if (offset,digest.hexdigest(),root)!=(header[4],header[6],header[7]):
        raise C09PagedCaptureHold('actual accounting atom full Source bytes/root/EOF differ')
    raw=b''.join(parts)
    from ..runtime.c09_canonical_json_stream_v2 import C09CanonicalJSONStreamV2
    parser=C09CanonicalJSONStreamV2(ensure_ascii=header[1]=='canonical-json.ascii.v1')
    parser.feed(raw,lambda event:None);parser.finish();parser._emit_callback=None
    return row[0],raw.decode('utf8'),row[2]


def _read_d13_original_fragment_v3(source,*,table,column,where,parameters,start,length,meter,builder):
    """Read the genuine published Source column across its registered physical layout."""
    from ..runtime.c09_paged_sql_v2 import legacy_cell_read_transaction_v2,read_legacy_sql_cell_fragment_v2
    if type(builder) is not _InstalledAuthorityRoleBuilderV2:raise C09PagedCaptureHold('actual installed D13 Source reader required')
