def _read_d13_cost_metadata_v3(builder,operation_id,meter):
    """Authenticate actual immutable Graph cost bytes; not a terminal verifier."""
    from .c09_model_budget_original_v1 import _json
    from ..runtime.d13_counter_cpu_accounting_v1 import (CPU_TABLE,BODY_TABLE,
        D13CounterCpuCostOriginalV1,D13CounterBodyCostOriginalV1,TABLE_DDLS)
    from ..runtime_contracts import NamespaceId
    from dataclasses import fields
    pair=_d13_frozen_graph_pair_v3(builder);namespace=builder.session._control.maintenance.namespace_id
    results=[]
    for table,cls in ((CPU_TABLE,D13CounterCpuCostOriginalV1),(BODY_TABLE,D13CounterBodyCostOriginalV1)):
        ddl=meter.read_fixed_row(pair.source,'sqlite_master',('sql',),'type=? AND name=?',('table',table))
        if ddl is None:results.append(None);continue
        expected=dict(TABLE_DDLS)[table]
        if ddl!=(expected,):raise C09PagedCaptureHold('actual D13 accounting original schema differs')
        row=meter.read_fixed_row(pair.source,table,('original_json','original_digest'),
            'bot=? AND persona=? AND operation_id=?',(*namespace.as_tuple,operation_id))
        if row is None:results.append(None);continue
        raw=_json(row[0])
        if type(raw) is not dict or set(raw)!={field.name for field in fields(cls)}:
            raise C09PagedCaptureHold('actual D13 accounting original exact fields differ')
        raw['namespace']=NamespaceId(**raw['namespace']);value=cls(**raw)
        if canonical_digest(asdict(value))!=row[1] or value.namespace!=namespace or value.operation_id!=operation_id or value.schema!=cls.__dataclass_fields__['schema'].default:
            raise C09PagedCaptureHold('actual D13 accounting source identity/complete commitment differs')
        results.append(value)
    pair.require_current()
    return tuple(results)


def _verify_d13_cost_terminal_join_v3(builder,frame,envelope,prepared,proof,costs,meter):
    """Join immutable cost originals to the actual installed terminal and reserve."""
    from .c09_model_budget_original_v1 import _json
