    value=_json(settlement[1])
    settlement_digest=canonical_digest({'ref':body.settlement_ref,'revision':settlement[0],'value':value})
    if (frame.cpu_reservation_ref!=prepared.budget_reservation_operation_id
            or frame.cpu_reservation_digest!=prepared.budget_reservation_digest
            or frame.parent_budget_lease_ref!=binding.parent_budget_lease_ref
            or frame.owner_grant_digest!=prepared.owner_grant_digest
            or frame.activation_generation!=binding.activation_generation):
        raise C09PagedCaptureHold('historical D13 header differs from actual CPU/Body reservation/preparation')
    if envelope is None:
        if terminal.status!='failed':raise C09PagedCaptureHold('only actual signed failed CPU terminal may lack full-wire count evidence')
    else:
        payload=envelope.payload
        if (payload.cpu_execution_id!=binding.execution_id or payload.cpu_worker_binding_digest!=binding.binding_digest
                or payload.cpu_claim_digest!=canonical_digest(proof.claim) or payload.cpu_input_digest!=binding.input_digest
                or payload.cpu_terminal_digest!=terminal.terminal_digest
                or terminal.actual_cpu_ms!=(payload.actual_cpu_ns+999999)//1000000
                or payload.cpu_settlement_ref!=body.settlement_ref or payload.cpu_settlement_digest!=settlement_digest
                or payload.d02_accounting_digest!=canonical_digest(body) or payload.d11_accounting_digest!=canonical_digest(cpu)):
            raise C09PagedCaptureHold('signed D13 evidence differs from actual journal/CPU/Body settlement originals')
    from ..runtime.jobs import _JOB_SELECT,_job_from_row
    from ..runtime.d11_types import job_graph_write
    columns=tuple(_JOB_SELECT.split(' FROM ',1)[0][len('SELECT '):].split(','))
    job_row=meter.read_fixed_row(pair.source,'runtime_jobs',columns,'job_id=?',(frame.job_id,))
    if job_row is None:raise C09PagedCaptureHold('historical D13 terminal job is absent')
    job=_job_from_row(job_row);write=job_graph_write(job)
    job_source=_read_d13_graph_atom_metadata_v3(builder,write.key.token,meter)
    job_atom=None if job_source is None else job_source[1:]
    if ((job.bot_id,job.persona_id)!=namespace.as_tuple or job.activity_id!=binding.activity_id
            or job.budget_ref!=binding.parent_budget_lease_ref or job.phase!=terminal.status
            or job_atom is None or job_atom[1]!=1 or _json(job_atom[0])!=write.value):
        raise C09PagedCaptureHold('historical D13 terminal job/projection differs from installed work')
    return settlement_digest


