def _read_d13_terminal_history_v3(builder,prepared,meter):
    """Read only indexed frozen rows; never inspect, begin, or reconcile work."""
    from .c09_paged_recovery_facts_v2 import _read_one
    from .c09_execution_connection_v1 import C09ExecutionOriginalsConnectionV1
    from .c09_role_capture_pair_v2 import InstalledC09RolePairV2
    from .internal_work_contract import InternalWorkTerminalProofV1
    from .contract import JournalHead
    from ..runtime.c09_paged_sql_v2 import legacy_cell_read_transaction_v2
    producer=builder.session._control._role_pairs.get('execution')
    if producer is None or type(producer.pair) is not InstalledC09RolePairV2:
        raise C09PagedCaptureHold('D13 terminal history requires actual frozen execution source')
    pair=producer.pair;pair.require_current()
    if pair._producer.session is not builder.session or pair.source_original.scope_digest!=builder.scope.scope_digest:
        raise C09PagedCaptureHold('D13 historical journal crossed actual capture scope')
    binding=prepared.binding;facts=builder.transform.facts
    facts.require_complete(scope_digest=builder.scope.scope_digest,facts_pin_digest=facts._completion.pin_digest)
    columns=('seq','mutation_id','request_digest','append_id','pending','previous_digest','chain_digest')
    indexed=[]
    for phase in ('claim','terminal'):
        row=_read_one(facts._db,
            'SELECT seq,execution_kind,business_operation_id,binding_digest,claim_digest FROM c09_recovery_journal_index_v2 WHERE scope_digest=? AND execution_id=? AND phase=?',
            (builder.scope.scope_digest,binding.execution_id,phase),meter)
        if row is not None:indexed.append((phase,row))
    if not indexed:return None
    if indexed[0][0]!='claim':raise C09PagedCaptureHold('actual D13 terminal lacks its indexed claim')
    from contextlib import ExitStack
    with ExitStack() as snapshots:
        for source in (pair.source,builder.pair.source,_d13_frozen_graph_pair_v3(builder).source):
            snapshots.enter_context(legacy_cell_read_transaction_v2(source))
        reader=C09ExecutionOriginalsConnectionV1(db=pair.source,
            control=builder.session._control.maintenance.control,namespace=builder.scope.authority_namespace)
        verifier=builder.session.require_fact_original_verifier_v2('internal',core_db=builder.pair.source,
            business_db=_d13_frozen_graph_pair_v3(builder).source,execution_reader=reader,algorithm=binding.algorithm_ref)
        decoded=[]
        for phase,index in indexed:
            if index[1:4]!=('internal',binding.operation_id,canonical_digest(binding)):
                raise C09PagedCaptureHold('actual indexed D13 journal identity differs from prepared binding')
            actual=meter.read_fixed_row(pair.source,'authority_v2_execution_entries',columns,'seq=?',(index[0],))
            if actual is None:raise C09PagedCaptureHold('actual indexed D13 journal row is absent')
            actual=tuple(actual)
            facts.require_execution_journal_row(pair.source_original,columns,actual,meter=meter)
            observed_binding,claim,terminal=reader._decode_internal_row(actual)
            if (observed_binding!=binding or canonical_digest(claim)!=index[4]
                    or (terminal is None)!=(phase=='claim')):
                raise C09PagedCaptureHold('actual D13 journal phase/binding/claim differs')
            decoded.append((actual,claim,terminal))
        if len(decoded)==1:return None
        first,claim,_=decoded[0];last,last_claim,terminal=decoded[1]
        if last_claim!=claim or last[0]<=first[0]:
            raise C09PagedCaptureHold('actual D13 terminal does not follow the same claim')
        if terminal.status=='unknown':return None
        if not verifier.verify_installed_terminal(binding,claim,terminal):
            raise C09PagedCaptureHold('actual historical D13 installed terminal signature differs')
        claim_receipt=reader._internal_append_receipt(first,binding,'claim')
        terminal_receipt=reader._internal_append_receipt(last,binding,'terminal')
        proof=InternalWorkTerminalProofV1(binding,claim,terminal,claim_receipt.receipt_ref,
            claim_receipt.content_digest,terminal_receipt.receipt_ref,terminal_receipt.content_digest,
            JournalHead(reader.journal_id,last[0],last[6]))
    pair.require_current()
    return proof


