def _verify_d13_http_history_v3(builder,key,meter):
    from .d13_provider_http_admission_v1 import verify_historical_provider_http_phase_v1
    table='authority_d13_provider_http_bindings_v1'
    expected_raw,expected_row=_read_d13_core_metadata_v3(builder,table,(*key[:2],'expected'),meter)
    intent,admission=_read_d13_http_model_origins_v3(builder,key[1],meter)
    service=builder.session.require_installed_d13_counter_service_v1()
    expected=verify_historical_provider_http_phase_v1(service,expected_raw,phase='expected',intent=intent,admission=admission)
    counter_key=(key[0],expected['counter_operation_id'],'evidence')
    service,frame,envelope,counted,_,_=_verify_d13_counter_history_v3(builder,counter_key,meter)
    _verify_d13_recorded_accounting_v3(builder,counter_key[1],frame,envelope,meter)
    template=expected['template_digest']
    if template==frame.raw_http_template_digest:counted_bytes=counted.raw_http_bytes
    elif template==frame.compressed_http_template_digest:counted_bytes=counted.compressed_http_bytes
    else:raise C09PagedCaptureHold('historical provider HTTP template is outside actual signed counter pair')
    if (expected['counter_evidence_digest']!=canonical_digest(envelope)
            or expected['frame_intent_digest']!=frame.frame_intent_digest or expected['authority_id']!=frame.authority_id
            or expected['call_id']!=frame.generation_call_id or expected['expires_at_utc']!=frame.expires_at_utc
            or expected['http_bytes']!=counted_bytes):
        raise C09PagedCaptureHold('historical expected HTTP phase lost actual frame/evidence/count/lifetime originals')
    observed_value=_read_d13_core_metadata_v3(builder,table,(*key[:2],'observed_before_send'),meter,required=False)
    if observed_value is None:
        if key[2]!='expected':raise C09PagedCaptureHold('historical observed HTTP phase lacks actual observed original')
        return expected_row,None
    observed_raw,observed_row=observed_value
    observed=verify_historical_provider_http_phase_v1(service,observed_raw,phase='observed_before_send',intent=intent,admission=admission)
    observed_at=observed['observed_at_utc'];import math
    if (type(observed_at) not in (int,float) or not math.isfinite(observed_at)
            or not frame.frozen_at_utc<=observed_at<frame.expires_at_utc
            or {**{name:value for name,value in observed.items() if name!='observed_at_utc'},'phase':'expected'}!=expected):
        raise C09PagedCaptureHold('historical observed HTTP phase differs from actual expected bytes/original lifetime')
    return expected_row,observed_row


