    refs.update(('history_selection',name,'*') for name in ('source_dependencies','read_set','raw_turn_refs','block_refs'))
    refs.add(('recent_history','*','completion_ref'))
    refs.update(('recent_history','*','turn',name) for name in ('audience_ref','raw_ref','source_ref','access_ref'))
    refs.add(('detail_history','*','source_ref'))
