    def _encode_origin(self,value,meter):
        """Preflight actual small origin DTO output, not Source body or permission."""
        from dataclasses import fields,is_dataclass
        from ..runtime_contracts import current_canonical_output_meter
        def size(item):
            if item is None:return 4
            if type(item) is bool:return 4 if item else 5
            if type(item) is int:
                text=str(item);meter.charge_encode(len(text));return len(text)
            if type(item) is str:
                return 2+sum(2 if char in {'"','\\','\b','\f','\n','\r','\t'} else
                    6 if ord(char)<32 or 127<=ord(char)<=65535 else 12 if ord(char)>65535 else 1 for char in item)
            if type(item) in (tuple,list):return 2+sum(size(child) for child in item)+max(0,len(item)-1)
            if type(item) is dict:
                return 2+sum(size(key)+1+size(child) for key,child in item.items())+max(0,len(item)-1)
            if is_dataclass(item) and not isinstance(item,type):
                actual_fields=fields(item)
                tag=type(item).__module__+'.'+type(item).__qualname__
                return 2+size('$type')+1+size(tag)+sum(1+size(field.name)+1+size(getattr(item,field.name)) for field in actual_fields)
            raise TypeError('historical origin summary is outside its exact named DTO profile')
        expected=size(value)
        if current_canonical_output_meter() is not meter:
            raise C09PagedCaptureHold('historical origin output lacks its actual parent canonical meter')
        meter.require_available(expected*2);self.capture.parser._require_arena(expected*4+4096)
        text=canonical_serialize(value)
        if len(text)!=expected:raise C09PagedCaptureHold('actual historical origin canonical size differs')
        encoded=text.encode('ascii');meter.charge_encode(len(encoded));return encoded

