            if not present:continue
            if (parser.references[(variant,'input','plan','plan_ref')]!=(key.token,1)
                    or parser.frozen_leaf_metadata[(variant,'input','plan','final_activity_id')]!=activity
                    or parser.frozen_leaf_metadata[(variant,'input','plan','final_operation_id')]!=post_c02_reply_operation_id(selector['c02_operation_id'],source['ref'])
                    or parser.frozen_leaf_metadata[(variant,'input','plan','final_effect_id')]!=natural_final_effect_id_v2(namespace,selector['c02_operation_id'],source['ref'])):
                raise C09PagedCaptureHold('actual prospective plan identity differs from its original C02/Source')
