def _verify_d13_root_unit_source_v3(capture,question,access):
    """Exact original C02 report projection; qualification authority remains separate."""
    from ..domains.d09 import ClaimKind
    if (type(question) is not _D13QuestionSourceReadV3 or question.capture is not capture
            or type(access) is not _D13RootAccessReadV3 or access.capture is not capture or access.question is not question):
        raise C09PagedCaptureHold('C02 unit projection needs actual same-capture Source and Access EOF')
    question.require_complete();access.require_complete();parser=capture.parser
    source=question.source_parser._source_metadata;characters=question.source_parser._source_text_characters
    from ..graph_types import AtomKey
