    from ..runtime.c09_paged_sql_v2 import current_c09_sql_meter_v2
    meter=current_c09_sql_meter_v2();root_token=question.reference.ref
    parser._require_arena(len(root_token)*64+4096);meter.require_available(len(root_token))
    root_key=AtomKey.from_token(root_token);meter.charge_encode(len(root_token))
    namespace=NamespaceId.from_key(root_key)
    closure=None
    for variant,present in parser.variant_presence.items():
        if not present:continue
        original=None
        for path,value in parser.root_unit_origins.items():
            if path[0]==variant:
                if original is not None:raise C09PagedCaptureHold('C02 unit source projection is ambiguous')
                original=value
        if original is None:raise C09PagedCaptureHold('C02 unit lacks original source projection')
        refs=original['source_refs']
        # AtomKey decoding, two derived tokens and sorting containers are local
        # temporaries; token lengths have no independent 4 KiB business bound.
        token_characters=sum(len(ref) for ref,revision in refs)
        parser._require_arena(token_characters*64+(len(refs)+1)*4096)
        if (not 1<=len(refs)<=256 or refs[0]!=(question.reference.ref,question.reference.version)
                or len({ref for ref,revision in refs})!=len(refs)):
            raise C09PagedCaptureHold('C02 unit Source closure lacks exact Root/order/unique ancestry inventory')
        accesses=[];corrections=[]
        for ref,revision in refs:
            meter.require_available(len(ref)*4+256)
            key=AtomKey.from_token(ref);meter.charge_encode(len(ref))
            if (revision<1 or NamespaceId.from_key(key)!=namespace
                    or key!=source_key(*namespace.as_tuple,key.owner.subject)):
                raise C09PagedCaptureHold('C02 unit ancestry crossed formal positive Source namespace/key')
            access_token=access_key(*namespace.as_tuple,key.owner.subject).token
            correction_token=source_correction_head_key(namespace,key.owner.subject).token
            meter.charge_encode(len(access_token)+len(correction_token))
            accesses.append(access_token);corrections.append(correction_token)
        actual_access=original['access_refs'];actual_correction=original['correction_refs']
        if (tuple(ref for ref,revision in actual_access)!=tuple(sorted(accesses))
                or any(revision<1 for ref,revision in actual_access)
                or actual_correction!=tuple((ref,0) for ref in sorted(corrections))
                or (access.reference.ref,access.reference.version) not in actual_access):
            raise C09PagedCaptureHold('C02 unit Source/Access/correction closure inventory differs from formal read versions')
        inventory=(refs,actual_access,actual_correction)
        if closure is not None and inventory!=closure:
            raise C09PagedCaptureHold('raw/compressed C02 unit complete ancestry inventories differ')
        closure=inventory
        from ..memory_types import _time
        _time(original['occurred_at'],'occurred_at',optional=True);_time(original['learned_at'],'learned_at')
        span=original['evidence_span']
        if (original['direct_quote'] is not False or original['attribution_required'] is not True
                or type(span) is not tuple or len(span)!=2 or any(type(value) is not int for value in span)):
            raise C09PagedCaptureHold('C02 unit original boolean/span field types differ')
        expected={'expires_at_utc':parser.frozen_leaf_metadata[(variant,'input','plan','valid_until_utc')],
            'kind':ClaimKind.REPORTED_CLAIM.value,'speaker_id':source['speaker_id'],
            'occurred_at':source['occurred_at'],'learned_at':source['recorded_at'],'source_kind':source['source_kind'],
            'assertion_status':source['assertion_status'],'d06_claim_kind':'attributed_report','attribution_required':True,
            'content_reality':'external_report','direct_quote':False,'direct_quote_span':None,'negation_cue_span':None,
            'evidence_span':(0,characters),'polarity_status':'unspecified_unreviewed','qualification_ref':None,
            'self_description_hypotheses':(),'semantic_constraints':(),'stance':None,'uncertainty':None}
        if source['source_kind'] not in {'reported','observed'} or any(original[name]!=value for name,value in expected.items()):
            raise C09PagedCaptureHold('actual C02 unit attributes/span differ from original Source report')
        for name in ('qualified_text','source_excerpt'):
            if original[name+'_sha256']!=question.text_hash.hexdigest() or original[name+'_characters']!=characters:
                raise C09PagedCaptureHold('actual C02 unit '+name+' differs from original complete Source')
