def begin_installed_authority_role_rebase_v2(session,role):
    """Factory accepts only an installed session; no rows, paths or facts DTO."""
    from .c09_paged_capture_control_v2 import C09PagedCaptureSessionV2
    from .c09_role_capture_pair_v2 import InstalledC09RolePairV2,C09RolePairProgressV2
    if type(session) is not C09PagedCaptureSessionV2 or role not in {'core','execution','deletion'}:
        raise AuthorityUnavailable('installed C09 authority role required')
    session.require_current()
    pair=session.open_role_pair(role)
    if type(pair) is C09RolePairProgressV2: return pair
    if type(pair) is not InstalledC09RolePairV2 or pair.source_original.scope_digest!=session.scope.scope_digest:
        raise AuthorityUnavailable('same installed role source and candidate required')
    basis=session.require_authority_role_basis_v2(pair)
    result=_InstalledAuthorityRoleBuilderV2(_BUILDER_TOKEN,session,pair,basis)
    return result


def _table_shape(source,table):
    if table!='sqlite_sequence': return read_c09_table_shape_v2(source,table)
    # SQLite's auto-increment metadata has a named natural-key codec.
    found=source.execute("SELECT sql FROM sqlite_master WHERE name='sqlite_sequence' AND type='table'").fetchone()
    if found!=('CREATE TABLE sqlite_sequence(name,seq)',):
        raise C09PagedCaptureHold('SQLite sequence schema differs')
    return C09TableShapeV2(table,('name','seq'),('name',),('text',),
        canonical_digest(('sylanne3.c09.sqlite-sequence-natural-key.v2',found[0])))


def _core_source_shape_v3(builder,physical,meter):
    from ..segmented_sql_cell_v1 import CORE_REF_DDLS_V2
    if builder.transform.role!='core' or physical.table not in CORE_REF_DDLS_V2 or 'payload_cell_id' not in physical.columns:
        return physical
    from ..runtime.c09_logical_source_v3 import read_c09_logical_source_shape_v3
    original=builder.core_logical_shapes_v3.get(physical.table)
    if original is None:
        scope=builder.session.begin_source_physical_read_v3(builder.pair,meter=meter)
        original=read_c09_logical_source_shape_v3(scope,physical.table,meter=meter)
        builder.core_logical_shapes_v3[physical.table]=original
    if original.physical_shape!=physical:
        raise C09PagedCaptureHold('actual Core Source physical/logical schema binding changed')
    return original


def _check_named_key(source,shape,key,meter):
    if shape.table=='sqlite_sequence':
        rows=source.execute('SELECT name FROM sqlite_sequence WHERE name=? LIMIT 2',key).fetchmany(2)
        meter.charge_read(sum(len(row[0].encode('utf-8')) for row in rows))
        if len(rows)!=1: raise C09PagedCaptureHold('SQLite sequence natural key is not unique')


def _require_tables(builder,meter):
    from ..runtime.c09_paged_sql_v2 import CAPTURE_DDLS_V2
    role=builder.transform.role
    required = legacy._CoreTransform.required_tables if role=='core' else (
        legacy._ExecutionTransform.required_tables if role=='execution' else legacy._DeletionTransform.required_tables)
    for table in required:
        if not _has_table(builder.pair.source,table,meter): raise C09PagedCaptureHold('required source table absent: '+table)
    if _has_table(builder.pair.source,'sqlite_sequence',meter):
        columns=('scope_digest','role','object_type','object_name','table_name','source_sql','target_sql','source_commitment')
        sql='CREATE TABLE sqlite_sequence(name,seq)'
        values=(builder.scope.scope_digest,role,'table','sqlite_sequence','sqlite_sequence',sql,sql,
                canonical_digest(('sylanne3.c09.sqlite-sequence-schema.v2',sql)))
        _same_insert(builder.pair.candidate,'authority_c09_role_schema_v2',columns,values,columns[:4],meter)
        if not _has_table(builder.pair.candidate,'sqlite_sequence',meter):
            raise C09PagedCaptureHold('installed AUTOINCREMENT table failed to generate sqlite_sequence')
    # Capture tables in an old source are immutable evidence, never omitted silently.
    for table in CAPTURE_DDLS_V2:
        if _has_table(builder.pair.source,table,meter):
            builder.basis.require_historical_capture_table(table,meter=meter)


def _register_data_stream(builder,source,shape,kind,meter,*,family=None):
    stream=_stream(builder.pair,builder.scope,shape,kind,family)
    with capture_transaction_v2(builder.pair.candidate):
        begin_capture_stream_v2(builder.pair.candidate,stream)
        _persist_stream(builder.pair,builder.scope,shape.table,kind,stream,meter)
    return stream


def _reduced_budget(budget,meter):
    remaining=budget.max_bytes-meter.related_read_bytes-meter.target_write_bytes-8192
    if remaining<=0: raise C09PagedCaptureHold('role descriptor needs its own continuation quantum')
    return replace(budget,max_bytes=remaining)


def _finish_state(builder,phase,position,meter):
    with capture_transaction_v2(builder.pair.candidate):
        _save_position(builder.pair,builder.scope,phase,position,meter)




def _advance_d13_draft_semantics_v3(builder,capture,meter):
    _verify_d13_draft_metadata_v3(builder,capture,meter)
    current=builder.d13_projection_v3
    if current is None or current.capture is not capture:
        current=_D13ProjectionReadV3(capture,'raw')
    if current.complete and current.quantum_completed and current.variant=='raw' and capture.parser.variant_presence['compressed']:
        current=_D13ProjectionReadV3(capture,'compressed',previous=current)
    if not (current.complete and current.quantum_completed):
        builder._pending_d13_projection_v3=current.advance(meter)
        return dict(status='progress',role='core',phase='d13_semantic_projection_'+current.variant,actual_io_bytes=meter.consumed_bytes)
    wanted={name for name,present in capture.parser.variant_presence.items() if present}
    if set(current.verified_variants)!=wanted or any(current.verified_variants[name]!=capture.parser.variant_metadata[name]['semantic_projection_digest'] for name in wanted):
        raise C09PagedCaptureHold('actual raw/compressed projection completion origins are incomplete')
    wire=builder.d13_wire_v3
    if wire is None or wire.capture is not capture:wire=_D13FrozenWireReadV3(capture,current)
    if not wire.all_complete():
        advanced=wire.advance(meter);builder._pending_d13_wire_v3=advanced
        return dict(status='progress',role='core',phase='d13_frozen_'+advanced.variant+'_'+advanced.stage,actual_io_bytes=meter.consumed_bytes)
    refs=builder.d13_graph_refs_v3
    if refs is None or refs.capture is not capture:refs=_D13HistoricalGraphRefsReadV3(capture,wire)
    if not (refs.complete and refs.quantum_completed):
        builder._pending_d13_graph_refs_v3=refs.advance(meter)
        return dict(status='progress',role='core',phase='d13_historical_graph_refs',actual_io_bytes=meter.consumed_bytes)
    refs.require_complete()
    question=builder.d13_question_source_v3
    if question is None or question.capture is not capture:question=_D13QuestionSourceReadV3(capture,refs,meter)
    if not (question.complete and question.quantum_completed):
        builder._pending_d13_question_source_v3=question.advance(meter)
        return dict(status='progress',role='core',phase='d13_question_source_original',actual_io_bytes=meter.consumed_bytes)
    question.require_complete()
    access=builder.d13_root_access_v3
    if access is None or access.capture is not capture:access=_D13RootAccessReadV3(capture,question,meter)
    if not (access.complete and access.quantum_completed):
        builder._pending_d13_root_access_v3=access.advance(meter)
        return dict(status='progress',role='core',phase='d13_root_access_original',actual_io_bytes=meter.consumed_bytes)
    access.require_complete()
    epoch=builder.d13_root_epoch_v3
    if epoch is None or epoch.capture is not capture:epoch=_D13RootEpochReadV3(capture,question,access)
    if not (epoch.complete and epoch.quantum_completed):
        builder._pending_d13_root_epoch_v3=epoch.advance(meter)
        return dict(status='progress',role='core',phase='d13_root_original_epoch',actual_io_bytes=meter.consumed_bytes)
    epoch.require_complete()
    _verify_d13_draft_c02_original_v3(builder,capture,meter)
    return None


